1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	// What a single item of each type is worth to the MHPCO: what it costs to
59	// insure, and what it is insured for. Keeping the two figures side by side
60	// makes this the one place that says which item types exist at all.
61	interface ItemTypeRates {
62	  basePremium: number;
63	  insuranceValue: number;
64	}
65	
66	const ITEM_TYPE_RATES: Record<string, ItemTypeRates> = {
67	  sword: { basePremium: 100, insuranceValue: 1000 },
68	  amulet: { basePremium: 60, insuranceValue: 600 },
69	  staff: { basePremium: 80, insuranceValue: 800 },
70	  potion: { basePremium: 40, insuranceValue: 400 },
71	  rune: { basePremium: 25, insuranceValue: 250 },
72	  moonstone: { basePremium: 25, insuranceValue: 250 },
73	};
74	
75	const LOYALTY_YEARS_THRESHOLD = 2;
76	const LOYALTY_DISCOUNT_RATE = 0.2;
77	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
78	const CURSE_SURCHARGE_RATE = 0.5;
79	const HIGH_ENCHANTMENT_THRESHOLD = 5;
80	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	const DEDUCTIBLE = 100;
84	const CAP_MULTIPLIER = 2;
85	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
86	const REDUCED_REIMBURSEMENT_RATE = 0.5;
87	
88	// The MHPCO's price list is closed: anything not on it cannot be insured.
89	const ratesFor = (type: string): ItemTypeRates => {
90	  const rates = ITEM_TYPE_RATES[type];
91	  if (rates === undefined) {
92	    throw new Error(`the MHPCO does not insure items of type ${type}`);
93	  }
94	  return rates;
95	};
96	
97	const unitBasePremium = (type: string): number => ratesFor(type).basePremium;
98	
99	const countByType = (items: Item[]): Map<string, number> =>
100	  items.reduce(
101	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
102	    new Map<string, number>(),
103	  );
104	
105	// A building block of 3 alike components is offered at a special base premium.
106	const basePremiumForItemGroup = (type: string, count: number): number =>
107	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
108	
109	const policyBasePremium = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
112	    0,
113	  );
114	
115	// Premium-side enchantment rule (threshold 5), distinct from the claim-side
116	// reduced-reimbursement rule (threshold 8).
117	const qualifiesForHighEnchantmentSurcharge = (item: Item): boolean =>
118	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
119	
120	const surchargeRate = (item: Item): number =>
121	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
122	  (qualifiesForHighEnchantmentSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
123	
124	// Item-specific modifiers apply to the affected item's own base premium, i.e.
125	// the unit price of its type — a block discount never shrinks a surcharge.
126	const itemSurcharge = (item: Item): number =>
127	  unitBasePremium(item.type) * surchargeRate(item);
128	
129	const itemSurcharges = (items: Item[]): number =>
130	  items.reduce((total, item) => total + itemSurcharge(item), 0);
131	
132	const isLongStanding = (customer: Customer): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
134	
135	// Policy-wide modifiers apply to the policy base premium only — never to the
136	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
137	// Every quote is a first insurance for its items, regardless of customer
138	// history, so that surcharge always applies.
139	const policyAdjustmentRate = (
140	  customer: Customer,
141	  isFollowUpContract: boolean,
142	): number =>
143	  FIRST_INSURANCE_SURCHARGE_RATE -
144	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
145	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
146	
147	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
148	// separate term rather than folded into a `base * 1.1` factor, which is not
149	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
150	const quotePremium = (
151	  items: Item[],
152	  customer: Customer,
153	  isFollowUpContract: boolean,
154	): number => {
155	  const base = policyBasePremium(items);
156	  return Math.ceil(
157	    base +
158	      itemSurcharges(items) +
159	      base * policyAdjustmentRate(customer, isFollowUpContract) +
160	      PROCESSING_FEE,
161	  );
162	};
163	
164	const unitInsuranceValue = (type: string): number =>
165	  ratesFor(type).insuranceValue;
166	
167	// The total payout per policy is capped at twice the insurance sum. Premium
168	// modifiers never reach the insurance sum: it is the plain sum of the unit
169	// values of the insured items.
170	const insuranceSum = (items: Item[]): number =>
171	  items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
172	
173	// A policy created by a quote step, tracked so later claims can pay out
174	// against it. `remainingCap` shrinks as successive claims are settled.
175	interface Policy {
176	  items: Item[];
177	  remainingCap: number;
178	}
179	
180	const openPolicy = (items: Item[]): Policy => ({
181	  items,
182	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
183	});
184	
185	// State accumulated by the steps run so far. Later steps price and pay out
186	// against what earlier steps established, so each step reads the state it was
187	// run with and returns the state the next step should see.
188	interface ScenarioState {
189	  customer: Customer;
190	  contractsSoFar: number;
191	  // Keyed by the zero-based index of the quote step that created the policy.
192	  policies: Map<number, Policy>;
193	}
194	
195	// A step's outcome: what to report, and how the scenario stands afterwards.
196	interface StepOutcome {
197	  result: Result;
198	  state: ScenarioState;
199	}
200	
201	// Records a policy against the step index that identifies it, leaving the
202	// state it was given untouched.
203	const withPolicy = (
204	  state: ScenarioState,
205	  policyId: number,
206	  policy: Policy,
207	): ScenarioState => ({
208	  ...state,
209	  policies: new Map(state.policies).set(policyId, policy),
210	});
211	
212	const quote = (
213	  step: QuoteStep,
214	  state: ScenarioState,
215	  stepIndex: number,
216	): StepOutcome => ({
217	  result: {
218	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
219	  },
220	  state: withPolicy(
221	    { ...state, contractsSoFar: state.contractsSoFar + 1 },
222	    stepIndex,
223	    openPolicy(step.items),
224	  ),
225	});
226	
227	// Claim-side enchantment rule (threshold 8), distinct from the premium-side
228	// high-enchantment surcharge (threshold 5).
229	const qualifiesForReducedReimbursement = (item: Item): boolean =>
230	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD;
231	
232	// Damage to heavily enchanted items is reimbursed at 50 % of the damage amount.
233	//
234	// The spec's other claim rule — "damage to items made of dragon material is
235	// fully reimbursed" — needs no code here, and its absence is not an oversight.
236	// Full reimbursement is already the default for items no clause applies to, so
237	// the dragon rule can only bite where it overrides something; and in the one
238	// case where the two compete (dragon material at enchantment >= 8) the spec
239	// gives the 50 % rule priority. No input distinguishes an implementation that
240	// reads `material` from one that ignores it, which is why `Item.material` is
241	// carried in the schema but never consulted.
242	const reimbursementRate = (item: Item): number =>
243	  qualifiesForReducedReimbursement(item) ? REDUCED_REIMBURSEMENT_RATE : 1;
244	
245	// A damage entry together with the specific insured item it was matched to.
246	interface MatchedDamage {
247	  damage: Damage;
248	  item: Item;
249	}
250	
251	// What a single damage entry entitles the claimant to, before the policy-wide
252	// cap is applied. A deductible applies per damage event, i.e. once per damaged
253	// item. Special clauses reduce the reimbursement first; the deductible comes
254	// off after.
255	const damageEntitlement = ({ damage, item }: MatchedDamage): number =>
256	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
257	
258	// Pairs each damage entry with a distinct insured item of the same type: two
259	// damages to "sword" refer to two different insured swords, not the same one
260	// twice. Instances of a type are consumed in the order they were insured.
261	const matchDamagesToItems = (
262	  insuredItems: Item[],
263	  damages: Damage[],
264	): MatchedDamage[] => {
265	  const unclaimed = [...insuredItems];
266	  return damages.map((damage) => {
267	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
268	    if (index === -1) {
269	      throw new Error(
270	        `the policy does not cover a damaged ${damage.itemType}`,
271	      );
272	    }
273	    return { damage, item: unclaimed.splice(index, 1)[0] };
274	  });
275	};
276	
277	// Reading a policy the scenario never opened is a programming error rather
278	// than a claimant's mistake, so this says so plainly instead of asserting the
279	// lookup succeeded and failing later with an incidental TypeError. Validating
280	// the claim step's policy index against the scenario is a separate concern,
281	// still to be specified.
282	const policyFor = (state: ScenarioState, policyId: number): Policy => {
283	  const policy = state.policies.get(policyId);
284	  if (policy === undefined) {
285	    throw new Error(`there is no policy ${policyId}`);
286	  }
287	  return policy;
288	};
289	
290	// The MHPCO does not reimburse a negative loss.
291	const rejectNegativeAmounts = (damages: Damage[]): void => {
292	  const negative = damages.find((damage) => damage.amount < 0);
293	  if (negative !== undefined) {
294	    throw new Error(
295	      `damage amount ${negative.amount} for ${negative.itemType} is negative`,
296	    );
297	  }
298	};
299	
300	// What the matched damages entitle the claimant to, before the policy-wide cap.
301	const claimEntitlement = (matchedDamages: MatchedDamage[]): number =>
302	  matchedDamages.reduce(
303	    (total, matched) => total + damageEntitlement(matched),
304	    0,
305	  );
306	
307	// The total payout per policy is capped: a claim gets at most what is left of
308	// the cap, and whatever it takes is no longer available to later claims. Both
309	// figures are derived here so they cannot drift apart.
310	const settleAgainstCap = (
311	  entitlement: number,
312	  remainingCap: number,
313	): ClaimResult => {
314	  // Payouts round down, in the MHPCO's favour. Rounding happens before the cap
315	  // is applied so that `remainingCap` is derived from the amount actually paid.
316	  const payout = Math.min(Math.floor(entitlement), remainingCap);
317	  return { payout, remainingCap: remainingCap - payout };
318	};
319	
320	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
321	  const policy = policyFor(state, step.policy);
322	  rejectNegativeAmounts(step.incident.damages);
323	  const matchedDamages = matchDamagesToItems(policy.items, step.incident.damages);
324	  const result = settleAgainstCap(
325	    claimEntitlement(matchedDamages),
326	    policy.remainingCap,
327	  );
328	  return {
329	    result,
330	    state: withPolicy(state, step.policy, {
331	      ...policy,
332	      remainingCap: result.remainingCap,
333	    }),
334	  };
335	};
336	
337	const runStep = (
338	  step: Step,
339	  state: ScenarioState,
340	  stepIndex: number,
341	): StepOutcome => {
342	  switch (step.op) {
343	    case "quote":
344	      return quote(step, state, stepIndex);
345	    case "claim":
346	      return claim(step, state);
347	  }
348	};
349	
350	// Where a scenario stands before any of its steps have run.
351	const initialState = (customer: Customer): ScenarioState => ({
352	  customer,
353	  contractsSoFar: 0,
354	  policies: new Map(),
355	});
356	
357	// The scenario part-way through: the results reported so far, and the state
358	// the next step will be run against.
359	interface ScenarioProgress {
360	  results: Result[];
361	  state: ScenarioState;
362	}
363	
364	// Each step is priced against the state the steps before it established, so
365	// the walk is sequential: fold the steps, threading the state from one to the
366	// next and collecting one result per step. The results array therefore mirrors
367	// the input steps in length and order.
368	export const runScenario = (scenario: Scenario): ScenarioResult => {
369	  const { results } = scenario.steps.reduce<ScenarioProgress>(
370	    ({ results, state }, step, stepIndex) => {
371	      const outcome = runStep(step, state, stepIndex);
372	      return { results: [...results, outcome.result], state: outcome.state };
373	    },
374	    { results: [], state: initialState(scenario.customer) },
375	  );
376	  return { results };
377	};
